local ran_ok, error = pcall(function() local kpse = require('kpse') kpse.set_program_name('luatex') local lfs = require("lfs") local cacheDir = "./_markdown_main" if lfs.isdir(cacheDir) == true then else assert(lfs.mkdir(cacheDir)) end local md = require("markdown") local convert = md.new({cacheDir = "./_markdown_main", contentBlocks = true, outputDir = ".", } ) local input = assert(io.open("memoria_TFG_esqueleto.md","r")):read("*a") print(convert(input:gsub("\r\n?", "\n"))) end) if not ran_ok then local file = io.open("./main.markdown.err", "w") if file then file:write(error .. "\n") file:close() end print('\\markdownError{An error was encountered while executing Lua code}{For further clues, examine the file "./main.markdown.err"}') end
